<div class="page-title clearfix"><h1><?php echo app_lang('financial_accounts'); ?></h1><div class="title-button-group"><?php echo modal_anchor(get_uri('financial_accounts/modal_form'),'Nueva cuenta',['class'=>'btn btn-default','title'=>'Nueva cuenta']); ?></div></div>
<div class="card"><div class="table-responsive"><table id="financial-accounts-table" class="display" width="100%"></table></div></div>
<div class="card mt15"><div class="card-header"><h4>Transferencia entre cuentas</h4></div><div class="card-body">
<?php echo form_open('financial_accounts/transfer',['id'=>'financial-transfer-form','class'=>'general-form']); ?><div class="row"><div class="col-md-3"><label>Cuenta origen</label><select name="source_account_id" class="form-control" required><option value="">Seleccione</option><?php foreach($accounts as $a): ?><option value="<?php echo (int)$a->id; ?>"><?php echo esc($a->name); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label>Cuenta destino</label><select name="destination_account_id" class="form-control" required><option value="">Seleccione</option><?php foreach($accounts as $a): ?><option value="<?php echo (int)$a->id; ?>"><?php echo esc($a->name); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label>Importe</label><input name="amount" class="form-control" inputmode="decimal" required></div><div class="col-md-2"><label>Fecha</label><input name="transfer_date" type="date" value="<?php echo get_today_date(); ?>" class="form-control" required></div><div class="col-md-2"><label>Concepto</label><input name="note" class="form-control"><button class="btn btn-primary mt10">Transferir</button></div></div><?php echo form_close(); ?>
</div></div>
<div class="card mt15"><div class="card-header"><h4>Transferencias recientes</h4></div><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Fecha</th><th>Origen</th><th>Destino</th><th>Importe</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($transfers as $t): ?><tr><td><?php echo (int)$t->id; ?></td><td><?php echo esc($t->transfer_date); ?></td><td><?php echo esc($t->source_name); ?></td><td><?php echo esc($t->destination_name); ?></td><td><?php echo to_currency($t->amount); ?></td><td><?php echo $t->status==='active'?'Activa':'Cancelada'; ?></td><td><?php if($t->status==='active'): ?><?php echo form_open('financial_accounts/cancel_transfer',['class'=>'general-form cancel-transfer-form']); ?><input type="hidden" name="id" value="<?php echo (int)$t->id; ?>"><input name="reason" placeholder="Motivo obligatorio" required><button class="btn btn-danger btn-xs">Reversar</button><?php echo form_close(); ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<script>$(function(){$('#financial-accounts-table').appTable({source:'<?php echo get_uri('financial_accounts/list_data'); ?>',columns:[{title:'Cuenta'},{title:'Tipo'},{title:'Moneda'},{title:'Saldo inicial'},{title:'Entradas'},{title:'Salidas'},{title:'Saldo actual'},{title:'Estado'}]});$('#financial-transfer-form,.cancel-transfer-form').appForm({onSuccess:function(){location.reload();}});});</script>
